-- TiDB lifecycle, placement, and sequence notice rules corpus
RENAME TABLE users TO users_old;
CREATE INDEX idx_email ON users (email);
CREATE UNIQUE INDEX idx_uniq ON users (email);
DROP INDEX idx_email ON users;
ALTER DATABASE app CHARACTER SET utf8mb4;
CREATE PROCEDURE p_cleanup() SELECT 1;
DROP PROCEDURE p_cleanup;
CREATE USER 'admin'@'%' IDENTIFIED BY 'secret';
ALTER USER 'admin'@'%' IDENTIFIED BY 'new_secret';
DROP USER 'admin'@'%';
GRANT SELECT ON app.users TO 'reader'@'%';
REVOKE SELECT ON app.users FROM 'reader'@'%';
CREATE ROLE manager;
DROP ROLE manager;
DROP RESOURCE GROUP rg1;
CREATE PLACEMENT POLICY p1 PRIMARY_REGION='us-east-1' REGIONS='us-east-1';
ALTER PLACEMENT POLICY p1 PRIMARY_REGION='us-west-1' REGIONS='us-west-1';
DROP PLACEMENT POLICY p1;
CREATE SEQUENCE seq1 START WITH 1 INCREMENT BY 1;
ALTER SEQUENCE seq1 START WITH 100;
DROP SEQUENCE seq1;
ALTER TABLE users ADD COLUMN email varchar(255);
ALTER TABLE users ADD PRIMARY KEY (id);
ALTER TABLE users ADD INDEX idx_email (email);
ALTER TABLE users ADD FOREIGN KEY (user_id) REFERENCES users(id);
ALTER TABLE users DROP COLUMN email;
ALTER TABLE users MODIFY COLUMN email varchar(500);
ALTER TABLE users DROP INDEX idx_email;
ALTER TABLE orders DROP FOREIGN KEY fk_user;
